class Solution:
    def lowestCommonAncestor(self, p: 'Node', q: 'Node') -> 'Node':
        seen = set()
        node = p
        while node:
            seen.add(node)
            node = node.parent
        node = q
        while node not in seen:
            node = node.parent
        return node

