class Solution {
public:
    Node* lowestCommonAncestor(Node* p, Node* q) {
        unordered_set<Node*> seen;
        for (Node* cur = p; cur != nullptr; cur = cur->parent) seen.insert(cur);
        Node* cur = q;
        while (seen.find(cur) == seen.end()) cur = cur->parent;
        return cur;
    }
};

