class Solution {
    public Node lowestCommonAncestor(Node p, Node q) {
        Set<Node> seen = new HashSet<>();
        for (Node cur = p; cur != null; cur = cur.parent) seen.add(cur);
        Node cur = q;
        while (!seen.contains(cur)) cur = cur.parent;
        return cur;
    }
}

